using System.ClientModel;
using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Implementations ---

/// <summary>Notebook that the agent uses to collect and organize findings.</summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Save a research note with a short title and detailed content. Use this to record important findings from web searches.")]
    public string SaveNote(string title, string content)
    {
        _notes.Add((title, content));
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  [Note saved: \"{title}\"]");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved with title \"{title}\".";
    }

    [Description("Retrieve all saved research notes so far.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note #{i + 1}: {n.Title} ---\n{n.Content}"));
    }
}

/// <summary>Simulated web search tool. Replace the body with a real search API (Bing, Google, etc.) for production use.</summary>
static class WebSearch
{
    // In-memory knowledge base used when no real search API key is configured.
    private static readonly Dictionary<string, string[]> SimulatedResults = new(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] =
        [
            "Quantum computing uses qubits that can exist in superposition, enabling parallel computation. IBM and Google have built processors exceeding 1000 qubits as of 2025.",
            "Key algorithms include Shor's algorithm for factoring and Grover's algorithm for search. Quantum error correction remains a major challenge.",
            "Applications span cryptography, drug discovery, materials science, and optimization problems. Commercial quantum advantage is expected in specific domains by 2027."
        ],
        ["artificial intelligence"] =
        [
            "Large language models like GPT-5 and Claude have demonstrated emergent reasoning capabilities. Multi-modal models now process text, images, audio, and video.",
            "AI agents that can use tools, browse the web, and write code are rapidly advancing. Frameworks like AutoGen and Semantic Kernel enable multi-agent orchestration.",
            "AI safety research focuses on alignment, interpretability, and governance. The EU AI Act and US executive orders establish regulatory frameworks."
        ],
        ["climate change"] =
        [
            "Global average temperatures have risen 1.2°C above pre-industrial levels. The Paris Agreement targets limiting warming to 1.5°C.",
            "Renewable energy capacity grew 50% in 2024, led by solar. Battery storage costs dropped 90% over the past decade.",
            "Climate impacts include more frequent extreme weather, rising sea levels, and biodiversity loss. Adaptation strategies are increasingly critical."
        ],
    };

    [Description("Search the web for information on a given query. Returns a list of relevant search result snippets.")]
    public static string Search(string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  [Searching: \"{query}\"]");
        Console.ResetColor();

        // Try to match against simulated results by keyword overlap
        foreach (var (key, results) in SimulatedResults)
        {
            if (query.Contains(key, StringComparison.OrdinalIgnoreCase)
                || key.Contains(query, StringComparison.OrdinalIgnoreCase))
            {
                return string.Join("\n\n", results.Select((r, i) => $"Result {i + 1}: {r}"));
            }
        }

        // Generic fallback for unknown queries
        return $"Result 1: Information about '{query}' is a rapidly evolving field with significant recent developments.\n\n"
             + $"Result 2: Researchers have published numerous studies on '{query}', highlighting both opportunities and challenges.\n\n"
             + $"Result 3: Industry leaders are investing heavily in '{query}', with major breakthroughs expected in coming years.";
    }
}

// --- Main program ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT");

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.WriteLine("Optionally set OPENAI_MODEL (default: gpt-4o-mini) and OPENAI_ENDPOINT.");
    Console.ResetColor();
    return;
}

// Build the chat client with tools
var notebook = new Notebook();

var clientOptions = new OpenAIClientOptions();
if (!string.IsNullOrWhiteSpace(endpoint))
    clientOptions.Endpoint = new Uri(endpoint);

var openAIClient = new OpenAIClient(new ApiKeyCredential(apiKey), clientOptions);

IChatClient client = openAIClient
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch.Search),
        AIFunctionFactory.Create(notebook.SaveNote),
        AIFunctionFactory.Create(notebook.GetAllNotes),
    ],
};

var systemPrompt = """
    You are a research agent. Your job is to research a topic the user provides.

    Follow this process:
    1. Break the topic into 2-3 sub-questions.
    2. For each sub-question, use the Search tool to find information.
    3. After each search, use SaveNote to record the key findings with a descriptive title.
    4. Once you have gathered enough information, use GetAllNotes to review your notes.
    5. Finally, provide a well-structured summary of your research to the user.

    Be thorough but concise. Cite specific facts and figures from your search results.
    """;

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine($"Researching: {topic}");
Console.ResetColor();
Console.WriteLine(new string('─', 50));

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic: {topic}"),
};

var response = await client.GetResponseAsync(messages, tools);

Console.WriteLine();
Console.WriteLine(new string('═', 50));
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("Research Summary:");
Console.ResetColor();
Console.WriteLine(new string('─', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('═', 50));

